package neural

import (
	"os"
	"path/filepath"
	"testing"
)

// The synthetic CI job supplies exports generated by CPU PyTorch immediately
// beforehand. No trained coefficients are stored in source control.
func TestPythonExportIntegrity(t *testing.T) {
	source := os.Getenv("COREPULSE_NEURAL_JOB_FIXTURE")
	if source == "" {
		t.Skip("external CPU PyTorch export is exercised by the synthetic CI job")
	}
	files := []string{"windows.csv", "split.json", "evaluation.json", "parity.json", "models/mlp_seed_7.json", "models/mlp_seed_23.json", "models/autoencoder_seed_7.json", "models/autoencoder_seed_23.json"}
	fixture := func(t *testing.T) string {
		t.Helper()
		dir := t.TempDir()
		for _, name := range files {
			b, e := os.ReadFile(filepath.Join(source, filepath.FromSlash(name)))
			if e != nil {
				t.Fatal(e)
			}
			target := filepath.Join(dir, filepath.FromSlash(name))
			if e = os.MkdirAll(filepath.Dir(target), 0755); e != nil {
				t.Fatal(e)
			}
			if e = os.WriteFile(target, b, 0600); e != nil {
				t.Fatal(e)
			}
		}
		return dir
	}
	t.Run("all-held-out-Go-predictions-match", func(t *testing.T) {
		raw, models, summaries, e := loadOutputs(fixture(t))
		if e != nil {
			t.Fatal(e)
		}
		if len(raw) == 0 || len(models) != 4 || len(summaries) != 4 {
			t.Fatal("missing exports")
		}
		for name, model := range models {
			if len(model.samples) != 6 || len(model.inputs) != 6 {
				t.Fatalf("missing held-out inputs for %s", name)
			}
		}
		manager := &Manager{job: Job{ID: "current", State: "complete"}, models: models}
		if _, _, e := manager.Predict("old", "mlp_seed_7", 0); e == nil {
			t.Fatal("stale job served inference")
		}
		if _, _, e := manager.Predict("current", "../weights", 0); e == nil {
			t.Fatal("unknown model accepted")
		}
		if _, _, e := manager.Predict("current", "mlp_seed_7", -1); e == nil {
			t.Fatal("negative sample accepted")
		}
		if _, sample, e := manager.Predict("current", "mlp_seed_7", 0); e != nil || sample.Truth == "" {
			t.Fatalf("Go inference did not run: %v", e)
		}
	})
	for _, name := range []string{"windows.csv", "models/mlp_seed_7.json", "split.json"} {
		t.Run("modified-"+filepath.Base(name), func(t *testing.T) {
			dir := fixture(t)
			file, e := os.OpenFile(filepath.Join(dir, filepath.FromSlash(name)), os.O_APPEND|os.O_WRONLY, 0600)
			if e != nil {
				t.Fatal(e)
			}
			file.WriteString("\n")
			file.Close()
			if _, _, _, e = loadOutputs(dir); e == nil {
				t.Fatal("modified source/artifact accepted")
			}
		})
	}
}
